"""BENCHMARK-ONLY adversarial practice opponents (TASK-CLAUDE-006). Not part of any submission.

One shared source, rendered into self-contained bot folders by build_adversaries.py:

  bluffer_low / bluffer_mid / bluffer_high
      A "calibrated" value/bluff bettor.  Value-bets by hand strength, semi-bluffs draws,
      c-bets and double-barrels air along NESTED lines (a hand that bluffs the river also
      bluffed the turn and flop, so bluffs follow a consistent story), sizes bets
      1/3-pot .. 1.3x-pot (polarised on the river), and check-raises with both monsters
      and draws.  The three variants differ only in the bluff-frequency multiplier
      (0.5x / 1.0x / 1.6x).  Preflop it plays a moderately wide open / 3-bet / 4-bet game.

  pressure
      Positional preflop pressure.  Wide small opens from the button, frequent 3-bets
      (value + light), 4-bets (value + wheel-ace style bluffs), and an effective-stack
      push/fold mode at <= 15 big blinds (approximate shove/call frequencies, ante
      aware).  Postflop it is deliberately plain (c-bet, value bet, give up) so that the
      preflop pressure is what is being stress-tested.

  adaptive
      The "bluffer_mid" game plan plus a MATCH-LOCAL tracker of the opponent's public
      behaviour (fold-to-bet by street, fold-to-open, fold-to-3-bet).  It scales its
      bluff frequency up against over-folding and down against calling stations, with
      exponentially decayed counts so it can re-adapt.  Memory lives only in this
      process (one process per match) and uses only the public action log.

These are DESIGNED STRESS TESTS, not equilibrium strategies and not forecasts of what
tournament entrants play.  Known intentional simplifications: made-hand classes are
coarse, equities are lookup-table guesses, board texture is ignored except for draws,
and bet sizing is fixed-menu.  They never see hidden cards: only the public
``game_state`` is read (own hole cards + board + public action log).

Rules: standard library only, no file, network or process-spawning use, deterministic: the same
state yields the same action ("chance" is a CRC32 hash of hand id, own cards,
board and a salt).  Written from scratch for this repo.
"""

import zlib

PROFILE = "bluffer_low"   # rewritten by build_adversaries.py

PROFILES = {
    "bluffer_low":  {"kind": "bluffer",  "bluff": 0.5},
    "bluffer_mid":  {"kind": "bluffer",  "bluff": 1.0},
    "bluffer_high": {"kind": "bluffer",  "bluff": 1.6},
    "pressure":     {"kind": "pressure", "bluff": 1.0},
    "adaptive":     {"kind": "adaptive", "bluff": 1.0},
}

RANKS = "23456789TJQKA"
AGGRESSIVE = ("raise", "all_in")
POSTS = ("ante", "small_blind", "big_blind")

# ---- nested-line bluff frequencies for air (before the profile multiplier) ----------
LINE_FREQ = {"flop": 0.50, "turn": 0.40, "river": 0.60}   # river is NOT nested; see calibration note in the TASK-006 report
SEMI_FREQ = {"flop": 0.65, "turn": 0.55}          # draws bet as semi-bluffs
CHECK_RAISE_VALUE = 0.35                          # OOP monsters that check to trap
CHECK_RAISE_BLUFF = 0.10                          # OOP draws that check-raise a bet
RAISE_BLUFF_IP = 0.05

# effective-stack push/fold schedule, (max eff stack in bb, frequency)
JAM_FREQ = [(4, 0.78), (6, 0.71), (8, 0.65), (10, 0.58), (12, 0.52), (15, 0.46)]
CALL_FREQ = [(4, 0.80), (6, 0.60), (8, 0.48), (10, 0.40), (12, 0.35), (15, 0.30)]


# --------------------------------------------------------------------------- hand tools
def _rv(card):
    return RANKS.index(card[0]) + 2


def _chen(cards):
    """Chen-style preflop score (monotone enough for a strength ranking)."""
    a, b = sorted((_rv(cards[0]), _rv(cards[1])), reverse=True)

    def pts(v):
        return {14: 10, 13: 8, 12: 7, 11: 6}.get(v, v / 2.0)

    s = pts(a)
    if a == b:
        return max(5.0, 2 * s)
    if cards[0][1] == cards[1][1]:
        s += 2
    gap = a - b - 1
    s -= {0: 0, 1: 1, 2: 2, 3: 4}.get(gap, 5)
    if gap <= 1 and a < 12:
        s += 1
    return s


def _build_pct_table():
    suits = "cdhs"
    deck = [r + s for r in RANKS for s in suits]
    scores = []
    for i in range(52):
        for j in range(i + 1, 52):
            scores.append(_chen((deck[i], deck[j])))
    scores.sort()
    return scores


_SCORES = _build_pct_table()


def pf_pct(cards):
    """Fraction of the 1326 starting hands this hand beats (ties count half), 0..1."""
    s = _chen(cards)
    lo = sum(1 for x in _SCORES if x < s)
    eq = sum(1 for x in _SCORES if x == s)
    return (lo + eq / 2.0) / len(_SCORES)


def made_strength(cards, board):
    """0 air, 1 weak pair, 2 top pair/overpair, 3 two pair, 4 trips-or-better.
    A made hand only counts when a hole card is part of it."""
    allc = list(cards) + list(board)
    vals = [_rv(c) for c in allc]
    hole = [_rv(c) for c in cards]
    bvals = [_rv(c) for c in board]
    counts = {}
    for v in vals:
        counts[v] = counts.get(v, 0) + 1
    trips = [v for v, n in counts.items() if n == 3]
    pairs = [v for v, n in counts.items() if n == 2]
    quads = [v for v, n in counts.items() if n == 4]
    suits = {}
    for c in allc:
        suits[c[1]] = suits.get(c[1], 0) + 1
    flush = any(n >= 5 and any(c[1] == s for c in cards) for s, n in suits.items())
    uniq = set(vals)
    if 14 in uniq:
        uniq.add(1)
    straight = False
    for lo in range(1, 11):
        window = set(range(lo, lo + 5))
        if window <= uniq and any(h in window or (h == 14 and 1 in window) for h in hole):
            straight = True
    if flush or straight or any(v in hole for v in quads) or any(v in hole for v in trips):
        return 4
    if trips and pairs and any(v in hole for v in pairs):
        return 4
    if len(pairs) >= 2 and any(v in hole for v in pairs):
        return 3
    held = [v for v in pairs if v in hole]
    if held:
        return 2 if max(held) >= max(bvals) else 1
    return 0


def draw_kind(cards, board):
    """'fd' flush draw, 'oesd', 'gut' or '' (only before the river, only with a hole card involved)."""
    if len(board) >= 5 or len(board) < 3:
        return ""
    allc = list(cards) + list(board)
    suits = {}
    for c in allc:
        suits[c[1]] = suits.get(c[1], 0) + 1
    for s, n in suits.items():
        if n == 4 and any(c[1] == s for c in cards):
            return "fd"
    vals = set(_rv(c) for c in allc)
    hole = set(_rv(c) for c in cards)
    outs = 0
    for r in range(2, 15):
        if r in vals and len(board) and r in set(_rv(c) for c in board) and r not in hole:
            continue
        test = set(vals) | {r}
        t2 = set(test)
        if 14 in t2:
            t2.add(1)
        for lo in range(1, 11):
            window = set(range(lo, lo + 5))
            if window <= t2 and (r in window or (r == 14 and 1 in window)) and any(
                    h in window or (h == 14 and 1 in window) for h in hole):
                outs += 1
                break
    # `outs` counts completing RANKS (a straight-draw rank = 4 cards)
    if outs >= 2:
        return "oesd"
    if outs == 1:
        return "gut"
    return ""


def equity_guess(strength, draw, street):
    base = {4: 0.93, 3: 0.82, 2: {"flop": 0.62, "turn": 0.58, "river": 0.50}[street],
            1: {"flop": 0.38, "turn": 0.33, "river": 0.28}[street], 0: 0.10}[strength]
    if strength <= 1 and street != "river":
        extra = {"fd": (0.30, 0.19), "oesd": (0.27, 0.17), "gut": (0.12, 0.08)}.get(draw)
        if extra:
            base += extra[0] if street == "flop" else extra[1]
    return min(base, 0.97)


# ------------------------------------------------------------------------ state helpers
def _u(state, salt):
    key = "%s|%s|%s|%s" % (state["hand_id"], ",".join(state["your_cards"]),
                           ",".join(state["community_cards"]), salt)
    return (zlib.crc32(key.encode()) & 0xFFFFFFFF) / 4294967296.0


def _plan_u(state):
    key = "%s|%s|plan" % (state["hand_id"], ",".join(state["your_cards"]))
    return (zlib.crc32(key.encode()) & 0xFFFFFFFF) / 4294967296.0


def _ctx(state):
    me = state["seat_to_act"]
    opp = [p for p in state["players"] if p["seat"] != me][0]
    log = state["action_log"]
    my_bet = state["your_bet_this_street"]
    opp_bet = opp["bet_this_street"]
    eff = min(state["your_stack"] + my_bet, opp["stack"] + opp_bet)
    bb = state["blinds"]["bb"]
    pre = [e for e in log if e["street"] == "preflop"]
    raises = [e for e in pre if e["action"] in AGGRESSIVE]
    return {
        "me": me, "opp": opp, "opp_id": opp["bot_id"], "bb": bb, "eff_bb": eff / float(bb),
        "ip": state["sb_seat"] == me,              # heads-up: the button/SB acts last postflop
        "n_raises": len(raises),
        "pf_aggr": bool(raises) and raises[-1]["seat"] == me,
        "opp_stack_after": opp["stack"],
    }


def _raise_to(state, target):
    """Legal raise to `target` (total street bet); all-in when it covers the stack; call if we cannot raise."""
    if state["amount_owed"] >= state["your_stack"]:
        return {"action": "call"}
    cap = state["your_bet_this_street"] + state["your_stack"]
    target = max(int(target), state["min_raise_to"])
    if target >= cap or cap - target < state["blinds"]["bb"]:
        return {"action": "all_in"}
    return {"action": "raise", "amount": target}


def _bet_frac(state, frac):
    """Bet/raise so the total street bet adds about frac * pot on top of the current bet."""
    return _raise_to(state, state["current_bet"] + max(state["blinds"]["bb"], int(state["pot"] * frac)))


def _check_or_fold(state):
    return {"action": "check"} if state["can_check"] else {"action": "fold"}


def _freq(table, eff_bb):
    for cap, f in table:
        if eff_bb <= cap:
            return f
    return 0.0


# ---------------------------------------------------------------------- adaptive tracker
class Tracker:
    """Match-local opponent statistics from public information only (see module docstring)."""

    DECAY = 0.985
    PRIOR_FOLD = 0.40
    PRIOR_N = 7.5

    def __init__(self):
        self.hand_id = None
        self.stats = {}          # key -> [folds, trials]
        self.seen_pairs = set()  # (hand_id, index) pairs already counted -> deduplication
        self.pending = None
        self.hands = 0

    def _add(self, key, folded):
        f, n = self.stats.get(key, [0.0, 0.0])
        self.stats[key] = [f + (1.0 if folded else 0.0), n + 1.0]

    def rate(self, key):
        f, n = self.stats.get(key, [0.0, 0.0])
        return (f + self.PRIOR_FOLD * self.PRIOR_N) / (n + self.PRIOR_N)

    def trials(self, key):
        return self.stats.get(key, [0.0, 0.0])[1]

    def _decay(self):
        for k in self.stats:
            self.stats[k][0] *= self.DECAY
            self.stats[k][1] *= self.DECAY

    def _resolve_pending_from_new_hand(self, state, ctx):
        """The previous hand ended without us seeing the opponent's reply. If our bet was not
        followed by any later decision, either they folded or the hand went to showdown/all-in.
        Fold iff our stack at the end of that hand equals stack-after-bet + pot-after-bet."""
        p = self.pending
        self.pending = None
        if not p:
            return
        my_posts = sum(e["amount"] for e in state["action_log"]
                       if e["seat"] == ctx["me"] and e["action"] in POSTS)
        end_stack = state["your_stack"] + my_posts
        folded = (not p["all_in"]) and end_stack == p["stack_after"] + p["pot_after"]
        self._add(p["key"], folded)

    def observe(self, state, ctx):
        hid = state["hand_id"]
        if hid != self.hand_id:
            self._resolve_pending_from_new_hand(state, ctx)
            self.hand_id = hid
            self.hands += 1
            self._decay()
        log = state["action_log"]
        # opponent replies that we can SEE (the hand continued, so they did not fold)
        for i in range(len(log) - 1):
            a, b = log[i], log[i + 1]
            if (hid, i) in self.seen_pairs:
                continue
            if a["seat"] == ctx["me"] and a["action"] in AGGRESSIVE and b["seat"] != ctx["me"] \
                    and b["street"] == a["street"] and b["action"] != "fold":
                self.seen_pairs.add((hid, i))
                if self.pending and self.pending["hand_id"] == hid and self.pending["index"] == i:
                    self.pending = None
                key = self._key(log, i)
                self._add(key, False)
        if len(self.seen_pairs) > 4000:
            self.seen_pairs = set(x for x in self.seen_pairs if x[0] == hid)

    @staticmethod
    def _key(log, i):
        a = log[i]
        if a["street"] == "preflop":
            n_before = sum(1 for e in log[:i] if e["street"] == "preflop" and e["action"] in AGGRESSIVE)
            return "pre_open" if n_before == 0 else "pre_3bet"
        return "bet_" + a["street"]

    def note_my_action(self, state, ctx, reply, pot_after, stack_after, all_in):
        """Called when we bet/raise: its reply may never become visible (fold ends the hand)."""
        log = state["action_log"]
        key = self._key(log + [{"street": state["street"], "action": "raise", "seat": ctx["me"]}],
                        len(log))
        self.pending = {"hand_id": state["hand_id"], "index": len(log), "key": key,
                        "pot_after": pot_after, "stack_after": stack_after, "all_in": all_in}


_TRACKER = Tracker()


def _bluff_mult(street_key):
    """Adaptive multiplier on bluff frequency from the opponent's fold rate to our bets."""
    if _TRACKER.trials(street_key) < 6:
        return 1.0
    fr = _TRACKER.rate(street_key)
    return max(0.15, min(2.2, 1.0 + 2.5 * (fr - 0.40)))


# ----------------------------------------------------------------------------- preflop
def _preflop(state, cfg):
    ctx = _ctx(state)
    kind = cfg["kind"]
    pct = pf_pct(state["your_cards"])
    bb = ctx["bb"]
    eff = ctx["eff_bb"]
    bet = state["current_bet"]
    owed = state["amount_owed"]
    nr = ctx["n_raises"]
    bluff = cfg["bluff"]
    u = _u(state, "pre")
    sb_first = (state["sb_seat"] == ctx["me"]) and nr == 0 and bet <= bb

    # ---- adaptive tweak of preflop bluff / open frequencies
    open_extra = 0.0
    bluff3 = 1.0
    if kind == "adaptive":
        fo = _TRACKER.rate("pre_open") if _TRACKER.trials("pre_open") >= 6 else 0.4
        f3 = _TRACKER.rate("pre_3bet") if _TRACKER.trials("pre_3bet") >= 6 else 0.4
        open_extra = max(-0.15, min(0.25, (fo - 0.40) * 0.6))
        bluff3 = max(0.2, min(2.2, 1.0 + 2.5 * (f3 - 0.40)))

    # ---- short-stack push/fold mode (all kinds at <= 8bb, pressure also up to 15bb, adaptive to 12bb)
    limit = {"pressure": 15, "adaptive": 12}.get(kind, 8)
    if eff <= limit:
        if sb_first:
            return {"action": "all_in"} if pct >= 1 - _freq(JAM_FREQ, eff) else {"action": "fold"}
        if nr >= 1:
            # facing a raise/jam
            commit = owed / float(max(1, state["your_stack"] + state["your_bet_this_street"]))
            if commit >= 0.5 or eff <= 8:
                need = 1 - _freq(CALL_FREQ, eff) * (1.0 if commit >= 0.9 else 0.8)
                return {"action": "call"} if pct >= need else {"action": "fold"}
            if pct >= 0.82 or (kind == "pressure" and pct >= 0.55 and u < 0.2):
                return {"action": "all_in"}
            return {"action": "call"} if pct >= 1 - _freq(CALL_FREQ, eff) * 0.8 else {"action": "fold"}
        if state["can_check"]:
            return {"action": "all_in"} if pct >= 0.85 else {"action": "check"}
        return {"action": "call"} if pct >= 0.45 else {"action": "fold"}

    # ---- parameters per kind
    if kind == "pressure":
        open_pct, open_size = 0.20, 2.2
        call_pct, value3, bluff3_band, bluff3_p = 0.40, 0.82, (0.35, 0.65), 0.22
        value4, bluff4_band, bluff4_p, call4_pct = 0.93, (0.50, 0.72), 0.30, 0.62
        jam5 = 0.96
    else:
        open_pct, open_size = 0.35 - open_extra, 2.5
        call_pct, value3, bluff3_band, bluff3_p = 0.45, 0.88, (0.30, 0.60), 0.06 * bluff * bluff3
        value4, bluff4_band, bluff4_p, call4_pct = 0.96, (0.55, 0.70), 0.10 * bluff, 0.72
        jam5 = 0.97

    if sb_first:                                       # button opens (limp-free)
        return _raise_to(state, open_size * bb) if pct >= open_pct else {"action": "fold"}
    if nr == 0:                                        # BB: facing a limp or checking the option
        if state["can_check"]:
            return _raise_to(state, 3 * bb) if pct >= 0.80 or (kind == "pressure" and u < 0.25 and pct > 0.3) \
                else {"action": "check"}
        return {"action": "call"}
    if nr == 1:                                        # facing an open
        if ctx["me"] == state["sb_seat"]:
            pass
        lo, hi = bluff3_band
        if pct >= value3 or (lo <= pct < hi and u < bluff3_p):
            return _raise_to(state, 3.0 * bet)
        return {"action": "call"} if pct >= call_pct else {"action": "fold"}
    if nr == 2:                                        # facing a 3-bet
        lo, hi = bluff4_band
        if pct >= value4 or (lo <= pct < hi and u < bluff4_p):
            return _raise_to(state, 2.3 * bet)
        return {"action": "call"} if pct >= call4_pct else {"action": "fold"}
    if pct >= jam5:
        return {"action": "all_in"}
    return {"action": "call"} if pct >= 0.93 else {"action": "fold"}


# ---------------------------------------------------------------------------- postflop
def _postflop(state, cfg):
    ctx = _ctx(state)
    kind = cfg["kind"]
    street = state["street"]
    board = state["community_cards"]
    strength = made_strength(state["your_cards"], board)
    draw = draw_kind(state["your_cards"], board)
    pot, owed = state["pot"], state["amount_owed"]
    ip = ctx["ip"]
    plan = _plan_u(state)
    u = _u(state, street)
    bluff = cfg["bluff"]
    if kind == "adaptive":
        bluff *= _bluff_mult("bet_" + street)

    my_bets_this_hand = [e for e in state["action_log"] if e["seat"] == ctx["me"] and e["action"] in AGGRESSIVE]
    bet_prev_street = any(e["street"] != street and e["street"] != "preflop" for e in my_bets_this_hand)
    aggressor = ctx["pf_aggr"]

    # ------------------------------------------------ facing a bet or raise
    if owed > 0:
        req = owed / float(pot + owed)
        eq = equity_guess(strength, draw, street)
        big = owed / float(max(1, pot - owed))
        if big >= 0.5:
            eq *= 0.92                                  # a bigger bet represents a stronger range
        if kind == "pressure":                          # plain postflop: pairs call, rest folds
            if strength >= 3:
                return _bet_frac(state, 0.9) if u < 0.4 else {"action": "call"}
            if strength == 2 and big <= 1.0:
                return {"action": "call"}
            if strength == 1 and big <= 0.4:
                return {"action": "call"}
            return {"action": "fold"}
        if strength >= 4:                               # value raise or call
            p_raise = 0.75 if street == "river" else 0.55
            if u < p_raise:
                return _raise_to(state, state["current_bet"] + max(owed * 1.6, pot * 0.6))
            return {"action": "call"}
        if draw in ("fd", "oesd") and street != "river" and not ip and u < CHECK_RAISE_BLUFF * bluff * 2:
            return _raise_to(state, state["current_bet"] + max(owed * 1.6, pot * 0.6))   # check-raise bluff
        if strength == 0 and street != "river" and big <= 0.45 and u < RAISE_BLUFF_IP * bluff:
            return _raise_to(state, state["current_bet"] * 3)                              # stab-raise a small bet
        if eq >= req + 0.03:
            return {"action": "call"}
        return {"action": "fold"}

    # ------------------------------------------------ checked to us (or we act first)
    # nested bluff line: air bets this street iff plan < frequency for the street
    line_freq = min(0.95, LINE_FREQ[street] * bluff)
    if kind == "pressure":
        if strength >= 2:
            return _bet_frac(state, 0.6)
        if strength == 0 and street == "flop" and aggressor and u < 0.55:
            return _bet_frac(state, 0.5)
        return {"action": "check"}

    if strength >= 4:
        if not ip and street != "river" and u < CHECK_RAISE_VALUE:
            return {"action": "check"}                  # trap: OOP monsters check-raise
        if street == "river":
            return _bet_frac(state, 1.3 if u < 0.35 else 0.8)
        return _bet_frac(state, 0.66 if u < 0.6 else 0.4)
    if strength == 3:
        return _bet_frac(state, 0.66) if u < 0.85 else {"action": "check"}
    if strength == 2:
        if ip or aggressor:
            return _bet_frac(state, 0.4) if u < 0.7 else {"action": "check"}
        return _bet_frac(state, 0.4) if u < 0.35 else {"action": "check"}
    if strength == 1:
        return _bet_frac(state, 0.33) if (ip and u < 0.15) else {"action": "check"}
    # air or missed/unfinished draws
    if draw and street != "river":
        if (ip or aggressor) and u < SEMI_FREQ[street]:
            return _bet_frac(state, 0.55)
        return {"action": "check"}
    # nested bluff: needs a credible story (we were the aggressor, or we bet before, or we are IP and it checked through)
    story = aggressor or bet_prev_street or ip
    gate = u if street == "river" else plan      # flop/turn bluffs are nested lines; the river gate is independent
    thr = line_freq if story else (line_freq * 0.5 if street == "river" else 0.0)   # OOP river probe-bluffs at half rate
    if gate < thr:
        if street == "river":
            return _bet_frac(state, 0.8 if u < 0.6 else 1.3)
        return _bet_frac(state, 0.5 if street == "flop" else 0.66)
    return {"action": "check"}


# ------------------------------------------------------------------------------ entry
def _bookkeep_after(state, reply):
    """Adaptive only: remember our aggressive action so the opponent's (possibly invisible) reply can be inferred."""
    if reply.get("action") not in ("raise", "all_in"):
        return
    ctx = _ctx(state)
    if reply["action"] == "all_in":
        inc = state["your_stack"]
    else:
        inc = reply["amount"] - state["your_bet_this_street"]
    _TRACKER.note_my_action(state, ctx, reply, state["pot"] + inc, state["your_stack"] - inc,
                            reply["action"] == "all_in")


def decide(game_state: dict) -> dict:
    if game_state.get("type") == "warmup":
        return {"action": "check"}
    cfg = PROFILES[PROFILE]
    try:
        if cfg["kind"] == "adaptive":
            _TRACKER.observe(game_state, _ctx(game_state))
        if game_state["street"] == "preflop":
            reply = _preflop(game_state, cfg)
        else:
            reply = _postflop(game_state, cfg)
        if cfg["kind"] == "adaptive":
            _bookkeep_after(game_state, reply)
        return reply
    except Exception:
        return _check_or_fold(game_state)
